"""Deep Space Tour's views: nebulae, star clusters, dying stars, galaxies, deep fields and the two black holes ever
imaged. Cut by ../solar-system/prep.py with TOUR=deep; see ../solar-system.md and ../deep-space.md for what the keys mean. `body` is the
object the tour moves between; `group` is what Settings → Show holds it on. Each object's views in the order the tour
shows them, best first. Real photos only: no artist's impressions, simulations or catalogue maps."""

HEADER = """# Deep Space Tour's views, cut by docs/solar-system/prep.py (TOUR=deep) from these originals. Public domain, CC BY or
# CC BY-SA; CC BY and CC BY-SA require this attribution. file\tbody\tcredit\tlicence\tsource\tcaption\tkind\tfocus x,y[,zoom]\tgroup
"""

HUBBLE = 'CC BY 4.0'


def whole(name, src, body, group, credit, licence, source, caption, **kw):
    """An object on dark sky, shown whole: the photo is already on black, so no levelling, just a soft edge."""
    d = dict(name=name, src=src, body=body, group=group, kind='disc', keepblack=True, box=(0, 0, 1, 1), margin=0, feather=0.05,
             cap=4096, credit=credit, licence=licence, source=source, caption=caption)
    d.update(kw)
    return {k: v for k, v in d.items() if v is not None}  # None drops a default (the black holes are levelled and boxed)


def closeup(name, src, body, group, credit, licence, source, caption, **kw):
    """A photo that fills the screen and pans."""
    return dict(name=name, src=src, body=body, group=group, kind='closeup', credit=credit, licence=licence, source=source,
                caption=caption, **kw)


