# Dense star fields compress badly; at 50 they look the same on screen and take about a third less room.
for _p in PHOTOS:
    if _p['name'] in {'andromeda', 'lmc', 'smc', 'milky-way-centre', 'milky-way', 'omega-centauri-core', 'omega-centauri', '47tuc',
                      'perseus', 'virgo', 'triangulum', 'antennae', 'ngc3603', 'pandora'}:
        _p.setdefault('quality', 50)
